import{af as t,z as a,J as r,ab as s}from"./chunks/framework.D7T92eqb.js";const f=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"devices/api/glossary.md","filePath":"devices/api/glossary.md"}'),d={name:"devices/api/glossary.md"};function o(i,e,n,l,c,h){return a(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792752607000"},[...e[0]||(e[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>A quick lookup for terms used in the device API. Follow the links for wire formats, supported operations and message-specific behavior.</p><h2 id="messages-and-fields" tabindex="-1">Messages and fields <a class="header-anchor" href="#messages-and-fields" aria-label="Permalink to &quot;Messages and fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Description</th></tr></thead><tbody><tr><td><a href="./protocol/">Message / frame</a></td><td>One unit of communication encoded using the Lightbug protocol. “Frame” refers to its encoded form on the wire.</td></tr><tr><td><a href="./messages/#types">Message type (MT)</a></td><td>The number identifying a message&#39;s purpose and payload format, such as MT35 for Device IDs. It is not an individual Message ID.</td></tr><tr><td><a href="./protocol/prefix">Prefix</a></td><td>Optional bytes before a message to help identify it in a byte stream: <code>0x4c, 0x42</code> (<code>LB</code> in ASCII).</td></tr><tr><td><a href="./protocol/headers">Header</a></td><td>Shared metadata fields such as Message ID, Method and Status. The outer version, length and message type are separate from header data in the <a href="./protocol/structure">message structure</a>.</td></tr><tr><td><a href="./protocol/structure#data">Payload</a></td><td>The message-specific data fields. A field named “Payload” may itself contain application bytes; its meaning is defined on the relevant message page.</td></tr><tr><td><a href="./protocol/headers">Header field ID</a></td><td>A <code>uint8</code> identifier selecting a shared header field, not the data type of its value. Also called a header field type.</td></tr><tr><td><a href="./messages/">Payload field ID</a></td><td>A <code>uint8</code> identifier selecting a field within a message&#39;s payload. Its meaning and value type depend on the message type. Also called a payload field type.</td></tr><tr><td>bBytes</td><td>A byte array that represents a length and that amount of data in bytes.<br>The length prefix is a <code>uint8</code> (1 byte) for data type IDs 0–127, or a little-endian <code>uint16</code> (2 bytes) for data type IDs 128–255.<br>A bByte entry for a sub-128 field might be <code>3 9 9 9</code>, where <code>3</code> is the length, and <code>9 9 9</code> is the data.<br> A bByte entry for a field with ID 128 or greater might be <code>3 0 9 9 9</code>, where <code>3</code> is the length, and <code>9 9 9</code> is the data.<br> See <a href="/docs/pr/26/devices/api/protocol/structure#bbytes">structure</a>.</td></tr><tr><td><a href="./protocol/#byte-breakdown">Little-endian</a></td><td>Byte order with the least-significant byte first, used for protocol integers.</td></tr></tbody></table><h2 id="identifiers-and-versions" tabindex="-1">Identifiers and versions <a class="header-anchor" href="#identifiers-and-versions" aria-label="Permalink to &quot;Identifiers and versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Description</th></tr></thead><tbody><tr><td><a href="./protocol/headers#1-message-id">Message ID</a></td><td>Identifies an individual message for tracking or correlating a reply; distinct from Message Type and Device ID.</td></tr><tr><td><a href="./protocol/headers#3-response-to">Response to</a></td><td>Identifies the request or subscription a message responds to. See <a href="./protocol/responses#correlating-a-reply">reply correlation</a>.</td></tr><tr><td><a href="./protocol/headers#2-client-id">Client ID</a></td><td>Identifies the client sending a message. Its interpretation depends on the context; Lightbug cloud services associate it with a Device ID.</td></tr><tr><td><a href="./messages/35-device-ids">Device ID</a></td><td>The Lightbug device identifier used by the cloud API, distinct from the modem&#39;s IMEI, the SIM&#39;s ICCID and the device serial number.</td></tr><tr><td><a href="./subscriptions/#ids">Subscription ID</a></td><td>Identifies a subscription within a message type. Omitting it addresses the default subscription, ID <code>0</code>.</td></tr><tr><td><a href="./protocol/structure">Protocol version</a></td><td>The version of the outer message encoding, currently V3. It is independent of Message Version and firmware version.</td></tr><tr><td><a href="./protocol/responses#message-format-versions">Message Version</a></td><td>Selects or identifies a message-specific payload format where supported. Supported values and defaults are defined by each message.</td></tr><tr><td><a href="./messages/34-device-status">Firmware version</a></td><td>Identifies the software running on a device. Its encoding depends on the target and is separate from protocol and message-format versions.</td></tr></tbody></table><h2 id="requests-and-updates" tabindex="-1">Requests and updates <a class="header-anchor" href="#requests-and-updates" aria-label="Permalink to &quot;Requests and updates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Description</th></tr></thead><tbody><tr><td><a href="./protocol/headers#5-method">Method</a></td><td>The requested operation, such as GET, SET, SUBSCRIBE or UNSUBSCRIBE. Supported methods and omission rules depend on the message.</td></tr><tr><td><a href="./protocol/responses#typed-responses-and-acks">ACK / typed response</a></td><td>An ACK (MT5) acknowledges another message; a typed response carries the operation&#39;s documented reply payload. Neither a reply nor an ACK necessarily means the operation is complete.</td></tr><tr><td><a href="./subscriptions/">Subscription / publication</a></td><td>A subscription requests later updates of a message type. A publication is an update, distinct from the subscription&#39;s <a href="./protocol/responses#subscription-replies-and-later-updates">control reply</a>.</td></tr><tr><td><a href="./protocol/responses#status-and-errors">Status</a></td><td>A shared header reporting the reply&#39;s outcome or progress. It is separate from any message-specific payload field named Status.</td></tr></tbody></table><h2 id="related-terminology" tabindex="-1">Related terminology <a class="header-anchor" href="#related-terminology" aria-label="Permalink to &quot;Related terminology&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Description</th></tr></thead><tbody><tr><td><a href="/docs/pr/26/terminology/positioning/gnss">GNSS / GPS</a></td><td>GNSS is satellite-based positioning; GPS is one of its satellite constellations.</td></tr><tr><td><a href="/docs/pr/26/terminology/positioning/rtk">RTK / correction data / RTCM</a></td><td>RTK improves GNSS positioning using correction data, commonly carried in RTCM formats.</td></tr><tr><td><a href="./sdks/toit/">Toit</a></td><td>A programming language for IoT devices, supported by the Lightbug SDK.</td></tr><tr><td><a href="https://en.wikipedia.org/wiki/ESP32" target="_blank" rel="noreferrer">ESP32</a></td><td>A microcontroller with WiFi and Bluetooth, used in some Lightbug devices.</td></tr></tbody></table>',10)])])}const u=t(d,[["render",o]]);export{f as __pageData,u as default};
